(function (global) {
  "use strict";
  function escapeHTML(str) {
    return String(str || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }
  function inlineFormat(text) {
    var replaced = escapeHTML(text || "");
    replaced = replaced.replace(/`([^`]+)`/g, "<code>$1</code>");
    replaced = replaced.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    replaced = replaced.replace(/\*([^*]+)\*/g, "<em>$1</em>");
    replaced = replaced.replace(/__(.+?)__/g, "<strong>$1</strong>");
    replaced = replaced.replace(/_(.+?)_/g, "<em>$1</em>");
    replaced = replaced.replace(/~~([^~]+)~~/g, "<del>$1</del>");
    replaced = replaced.replace(/\[(.+?)\]\((.+?)\)/g, function (_, label, href) {
      var link = href || "";
      if (/^javascript:/i.test(link)) {
        return label;
      }
      return '<a href="' + escapeHTML(link) + '" target="_blank" rel="noopener">' + label + "</a>";
    });
    return replaced;
  }
  function MarkdownIt() {}
  MarkdownIt.prototype.render = function (text) {
    var lines = String(text || "").replace(/\r\n/g, "\n").split("\n"),
      html = [],
      in_code = false,
      code_buffer = [],
      list_state = null;
    function closeList() {
      if (list_state) {
        html.push(list_state === "ol" ? "</ol>" : "</ul>");
        list_state = null;
      }
    }
    lines.forEach(function (line) {
      var trimmed = line.trim(),
        heading_match,
        list_match;
      if (/^```/.test(trimmed)) {
        if (!in_code) {
          closeList();
          in_code = true;
          code_buffer = [];
        } else {
          html.push('<pre><code>' + escapeHTML(code_buffer.join("\n")) + "</code></pre>");
          code_buffer = [];
          in_code = false;
        }
        return;
      }
      if (in_code) {
        code_buffer.push(line);
        return;
      }
      if (!trimmed) {
        closeList();
        html.push("<p></p>");
        return;
      }
      heading_match = trimmed.match(/^(#{1,6})\s+(.*)$/);
      if (heading_match) {
        closeList();
        html.push(
          "<h" + heading_match[1].length + ">" +
            inlineFormat(heading_match[2]) +
            "</h" + heading_match[1].length + ">"
        );
        return;
      }
      list_match = trimmed.match(/^([*+-]|\d+\.)\s+(.*)$/);
      if (list_match) {
        var marker = list_match[1],
          content = list_match[2];
        if (!list_state) {
          list_state = /\d/.test(marker) ? "ol" : "ul";
          html.push(list_state === "ol" ? "<ol>" : "<ul>");
        } else if (
          (list_state === "ol" && !/\d/.test(marker)) ||
          (list_state === "ul" && /\d/.test(marker))
        ) {
          closeList();
          list_state = /\d/.test(marker) ? "ol" : "ul";
          html.push(list_state === "ol" ? "<ol>" : "<ul>");
        }
        html.push("<li>" + inlineFormat(content) + "</li>");
        return;
      }
      closeList();
      html.push("<p>" + inlineFormat(trimmed) + "</p>");
    });
    closeList();
    if (in_code) {
      html.push('<pre><code>' + escapeHTML(code_buffer.join("\n")) + "</code></pre>");
    }
    return html.join("");
  };
  function factory(options) {
    return new MarkdownIt(options || {});
  }
  if (typeof module !== "undefined" && module.exports) {
    module.exports = factory;
  }
  global.markdownit = factory;
}(this));
